// Map Meta Insights rows -> Notion page payloads
const dbId = $env.NOTION_DB_ID;
const rows = ($input.first().json.data) || [];
const num = (v) => (v === undefined || v === null || v === '') ? null : parseFloat(v);
const platMap = {
  facebook: 'Meta - Facebook',
  instagram: 'Meta - Instagram',
  audience_network: 'Meta - Facebook',
  messenger: 'Meta - Facebook'
};
const leadKeys = [
  'lead',
  'onsite_conversion.lead_grouped',
  'onsite_conversion.messaging_conversation_started_7d'
];
const out = [];
for (const r of rows) {
  let cpl = null;
  const cpa = r.cost_per_action_type || [];
  for (const k of leadKeys) {
    const f = cpa.find(a => a.action_type === k);
    if (f) { cpl = parseFloat(f.value); break; }
  }
  const platform = platMap[r.publisher_platform] || 'Meta - Facebook';
  const cname = r.campaign_name || 'Unknown';
  const code = String(cname).match(/AD0\d|ST0\d|CR0\d/);
  const properties = {
    'Name': { title: [ { text: { content: `${r.date_start} · ${platform} · ${cname}` } } ] },
    'Date': { date: { start: r.date_start } },
    'Platform': { select: { name: platform } },
    'Placement': { select: { name: 'Feed' } },
    'Spend (THB)': { number: num(r.spend) },
    'Impressions': { number: num(r.impressions) },
    'Reach': { number: num(r.reach) },
    'Clicks': { number: num(r.clicks) },
    'CTR %': { number: num(r.ctr) },
    'CPM (THB)': { number: num(r.cpm) },
    'CPC (THB)': { number: num(r.cpc) },
    'CPL (THB)': { number: cpl },
    'Status': { select: { name: 'Running' } },
    'Notes': { rich_text: [ { text: { content: 'Auto-synced from Meta Insights via n8n (WF3)' } } ] }
  };
  if (code) properties['Ad Campaign'] = { select: { name: code[0] } };
  out.push({ json: { parent: { database_id: dbId }, properties } });
}
return out;

// Map TikTok integrated report rows -> Notion page payloads
const dbId = $env.NOTION_DB_ID;
const resp = $input.first().json;
const list = (resp.data && resp.data.list) || [];
const num = (v) => (v === undefined || v === null || v === '') ? null : parseFloat(v);
const out = [];
for (const item of list) {
  const d = item.dimensions || {};
  const mt = item.metrics || {};
  const day = String(d.stat_time_day || '').slice(0, 10);
  const cname = mt.campaign_name || d.campaign_id || 'Unknown';
  const code = String(cname).match(/AD0\d|ST0\d|CR0\d/);
  const properties = {
    'Name': { title: [ { text: { content: `${day} · TikTok · ${cname}` } } ] },
    'Date': { date: { start: day } },
    'Platform': { select: { name: 'TikTok' } },
    'Placement': { select: { name: 'In-feed' } },
    'Spend (THB)': { number: num(mt.spend) },
    'Impressions': { number: num(mt.impressions) },
    'Reach': { number: num(mt.reach) },
    'Clicks': { number: num(mt.clicks) },
    'CTR %': { number: num(mt.ctr) },
    'CPM (THB)': { number: num(mt.cpm) },
    'CPC (THB)': { number: num(mt.cpc) },
    'CPL (THB)': { number: num(mt.cost_per_conversion) },
    'Status': { select: { name: 'Running' } },
    'Notes': { rich_text: [ { text: { content: 'Auto-synced from TikTok Reporting via n8n (WF3)' } } ] }
  };
  if (code) properties['Ad Campaign'] = { select: { name: code[0] } };
  out.push({ json: { parent: { database_id: dbId }, properties } });
}
return out;
